// ---- shared prelude (the generator puts this at the top of every engine Code node) ----
const cfg = $('Config').first().json;
const flow = cfg.flow || {};
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const today = cfg.today_override || new Date().toLocaleDateString('en-CA', { timeZone: cfg.timezone || 'UTC' });
const ymdOf = s => String(s ?? '').trim().slice(0, 10);
const isYmd = s => /^\d{4}-\d{2}-\d{2}$/.test(s) && new Date(s + 'T00:00:00Z').toISOString().slice(0, 10) === s;
const addDays = (ymd, n) => { const d = new Date(ymd + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const daysBetween = (a, b) => Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
const isEmail = s => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(s || ''));
const lc = x => String(x ?? '').trim().toLowerCase();
const yes = v => lc(v) === 'yes';
const get = (o, p) => String(p).split('.').reduce((a, k) => (a == null ? undefined : a[k]), o);
const lookup = (ctx, k) => { const v = get(ctx, k); return v === undefined ? get(cfg, k) : v; };
const fmtMoney = n => '$' + (Math.round(Number(n) * 100) / 100).toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 2 });
// Plain text with {{placeholders}} -> safe HTML (template text and values escaped, bare URLs linked, blank line = new paragraph).
const render = (tpl, ctx) => String(tpl ?? '').split(/\n\s*\n/).map(par => {
  let h = par.replace(/[<>&"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  h = h.replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => esc(lookup(ctx, k) ?? ''));
  h = h.replace(/(https?:\/\/[^\s<]+?)([.,;:!?)]*)(?=\s|<|$)/g, '<a href="$1">$1</a>$2').replace(/\n/g, '<br>');
  return '<p>' + h + '</p>';
}).join('\n');
// Subject lines: plain text, no line breaks (prevents header injection).
const renderText = (tpl, ctx) => String(tpl ?? '').replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_, k) => String(lookup(ctx, k) ?? '')).replace(/[\r\n]+/g, ' ').trim();
const match = (c, ctx) => {
  if (!c) return true;
  if (Array.isArray(c)) return c.every(x => match(x, ctx));
  if (c.any) return c.any.some(x => match(x, ctx));
  if (c.all) return c.all.every(x => match(x, ctx));
  if (c.not) return !match(c.not, ctx);
  const raw = get(ctx, c.field); const s = lc(raw); const n = parseFloat(raw);
  const num = x => (typeof x === 'string' && x.startsWith('cfg.') ? parseFloat(get(cfg, x.slice(4))) : x);
  if ('equals' in c) return s === lc(c.equals);
  if ('in' in c) return c.in.map(lc).includes(s);
  if ('in_cfg' in c) return (get(cfg, c.in_cfg) || []).map(lc).includes(s);
  if ('contains' in c) return s.includes(lc(c.contains));
  if ('contains_any' in c) return c.contains_any.some(w => s.includes(lc(w)));
  if ('empty' in c) return (s === '') === !!c.empty;
  if ('gte' in c) return Number.isFinite(n) && n >= num(c.gte);
  if ('lte' in c) return Number.isFinite(n) && n <= num(c.lte);
  if ('gt' in c) return Number.isFinite(n) && n > num(c.gt);
  if ('lt' in c) return Number.isFinite(n) && n < num(c.lt);
  if ('lte_field' in c) { const o = parseFloat(get(ctx, c.lte_field)); return Number.isFinite(n) && Number.isFinite(o) && n <= o; }
  return false;
};
// Validates a payload against a field list. Returns { v: cleaned values, errors: [...] }.
const validateFields = (fields, b) => {
  const v = {}; const errors = [];
  for (const f of fields) {
    const s0 = b[f.key] == null ? '' : String(b[f.key]).trim();
    if (!s0) { if (f.required) errors.push('missing ' + f.key); v[f.key] = f.default_today ? today : (f.default ?? ''); continue; }
    let s = s0;
    switch (f.type || 'text') {
      case 'email': s = s.toLowerCase(); if (!isEmail(s)) errors.push('invalid ' + f.key); break;
      case 'phone': if (s.replace(/\D/g, '').length < 7) errors.push('invalid ' + f.key); s = s.slice(0, 30); break;
      case 'url': if (!/^https?:\/\/\S+$/i.test(s)) errors.push(f.key + ' must be a http(s) link'); s = s.slice(0, 500); break;
      case 'date': {
        if (!isYmd(s)) { errors.push(f.key + ' must be YYYY-MM-DD'); break; }
        const d = daysBetween(today, s);
        if (f.min_days_ahead != null && d < f.min_days_ahead) errors.push(f.key + ' is too soon');
        if (f.max_days_ahead != null && d > f.max_days_ahead) errors.push(f.key + ' is too far ahead');
        break;
      }
      case 'time': if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(s)) errors.push(f.key + ' must be HH:MM (24h)'); break;
      case 'number': { const n = parseFloat(s); if (!Number.isFinite(n) || (f.min != null && n < f.min) || (f.max != null && n > f.max)) errors.push('invalid ' + f.key); else s = n; break; }
      case 'select': { const hit = (f.options || []).find(o => lc(o) === lc(s)); if (hit === undefined) errors.push(f.key + ' must be one of: ' + (f.options || []).join(', ')); else s = hit; break; }
      default: s = s.slice(0, f.max_length || 1000);
    }
    v[f.key] = s;
  }
  return { v, errors };
};
const authFails = item => !!cfg.webhook_secret && (item.json.headers || {})['x-webhook-secret'] !== cfg.webhook_secret;
const newId = prefix => prefix + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
const markSeen = (store, key) => {
  store.seen = store.seen || {};
  const keys = Object.keys(store.seen);
  if (keys.length > 500) for (const k of keys) if (store.seen[k] < addDays(today, -3)) delete store.seen[k];
  store.seen[key] = today;
};
const isSeen = (store, key) => !!(store.seen && store.seen[key] === today);
const withFooter = (html, marketing) => marketing && cfg.optout_footer ? html + `<p style="color:#777;font-size:12px">${esc(cfg.optout_footer)}</p>` : html;
// ---- end prelude ----

// Incident logic: groups repeated alerts into one incident, alerts once, reminds periodically, and closes on recovery.
// Accepts uptime-monitor webhooks (status down/up, or common synonyms) and n8n Error Trigger payloads (status error).
const store = $getWorkflowStaticData('global');
store.incidents = store.incidents || {}; store.errors = store.errors || {};
const DOWN = ['down', 'offline', 'failed', 'failure', 'critical', 'started', 'triggered', 'alert', 'firing', '1'];
const UP = ['up', 'online', 'recovered', 'resolved', 'ok', 'healthy', '2'];
const now = Number(cfg.now_override || Date.now());
const mins = Number;
const out = [];
for (const it of $('Trigger').all()) {
  const dry = cfg.dry_run === true;
  const j = it.json;
  let monitor, status, message, url, sev, isErr = false;
  if (j.workflow && j.execution) { isErr = true; monitor = j.workflow.name; status = 'error'; message = (j.execution.error && j.execution.error.message) || 'workflow failed'; url = j.execution.url || ''; }
  else {
    if (authFails(it)) { out.push({ json: { status: 'unauthorized', dry_run: dry } }); continue; }
    const b = j.body || {};
    monitor = String(b.monitor || b.monitorFriendlyName || b.name || '').trim();
    const raw = lc(b.status ?? b.alertType ?? b.state ?? '');
    status = DOWN.includes(raw) ? 'down' : UP.includes(raw) ? 'up' : raw === 'error' ? 'error' : '';
    message = String(b.message || b.alertDetails || b.error || '').slice(0, 500); url = String(b.url || b.monitorURL || '').slice(0, 300); sev = lc(b.severity);
    const errs = []; if (!monitor) errs.push('missing monitor'); if (!status) errs.push('status must be down, up or error (got "' + raw + '")');
    if (errs.length) { out.push({ json: { status: 'invalid', errors: errs, dry_run: dry } }); continue; }
    isErr = status === 'error';
  }
  if (!['critical', 'major', 'minor'].includes(sev || '')) {
    sev = cfg.default_severity || 'major';
    for (const r of cfg.severity_rules || []) if ((r.contains_any || []).some(w => lc(monitor).includes(lc(w)))) { sev = r.severity; break; }
  }
  const clientEmail = (cfg.clients || {})[monitor] || '';
  const base = { dry_run: dry, monitor, severity: sev, message, url };
  const ctx = { monitor, severity: sev, message: message || 'no details', url: url || '(none)', today, client_email: clientEmail };
  const alertTo = sev === 'critical' && cfg.oncall_email ? cfg.oncall_email : cfg.owner_email;
  const mk = (action, extra) => ({ json: { ...base, status: 'new', action, owner_to: alertTo, ...extra } });
  if (isErr) {
    const last = store.errors[monitor];
    if (!last || now - last.t >= mins(cfg.suppress_minutes ?? 30) * 60000) {
      const n = last ? last.n : 0;
      const id = newId('INC');
      if (!dry) store.errors[monitor] = { t: now, n: 0 };
      out.push(mk('error_alert', { id, row: { incident_id: id, monitor, client: clientEmail, url, severity: sev, status: 'logged', opened_at: today, message, alerts_sent: 1 },
        owner_subject: renderText(flow.error.subject, { ...ctx, suppressed: n }), owner_html: render(flow.error.body, { ...ctx, suppressed: n }) }));
    } else { if (!dry) last.n++; out.push({ json: { ...base, status: 'suppressed', action: 'none' } }); }
    continue;
  }
  const inc = store.incidents[monitor];
  if (status === 'down') {
    if (!inc) {
      const id = newId('INC');
      if (!dry) store.incidents[monitor] = { id, opened: now, last_alert: now, count: 1 };
      out.push(mk('open', { id, row: { incident_id: id, monitor, client: clientEmail, url, severity: sev, status: 'open', opened_at: today, message, closed_at: '', duration_min: '', alerts_sent: 1 },
        owner_subject: renderText(flow.open.subject, ctx), owner_html: render(flow.open.body, ctx),
        draft_to: clientEmail, draft_subject: clientEmail ? renderText(flow.client_open.subject, ctx) : '', draft_html: clientEmail ? render(flow.client_open.body, ctx) : '' }));
    } else {
      inc.count++;
      if (now - inc.last_alert >= mins(cfg.reminder_minutes ?? 60) * 60000) {
        const dur = Math.round((now - inc.opened) / 60000);
        if (!dry) inc.last_alert = now;
        out.push(mk('reminder', { id: inc.id, owner_subject: renderText(flow.reminder.subject, { ...ctx, minutes: dur }), owner_html: render(flow.reminder.body, { ...ctx, minutes: dur }) }));
      } else out.push({ json: { ...base, status: 'suppressed', action: 'none' } });
    }
  } else if (status === 'up') {
    if (!inc) { out.push({ json: { ...base, status: 'ignored', action: 'none' } }); continue; }
    const dur = Math.round((now - inc.opened) / 60000);
    if (!dry) delete store.incidents[monitor];
    out.push(mk('resolve', { id: inc.id, row: { incident_id: inc.id, status: 'resolved', closed_at: today, duration_min: dur },
      owner_subject: renderText(flow.resolved.subject, { ...ctx, minutes: dur }), owner_html: render(flow.resolved.body, { ...ctx, minutes: dur }),
      draft_to: clientEmail, draft_subject: clientEmail ? renderText(flow.client_resolved.subject, { ...ctx, minutes: dur }) : '', draft_html: clientEmail ? render(flow.client_resolved.body, { ...ctx, minutes: dur }) : '' }));
  }
}
return out;
